// Looks up a word's meaning, case/whitespace-insensitive. Returns undefined
// if the word isn't in the built-in dictionary (e.g. a brand-new word a user
// typed into "Insert Word" with no meaning of their own).
function getMeaning(word) {
  return WORD_MEANINGS[String(word).trim().toLowerCase()];
}

// Returns up to `count` words straight from WORD_BANK (all real words --
// never invented). Capped at WORD_BANK.length since there's nothing to
// generate; pass no argument to get every word in the bank.
function generateWordList(count = WORD_BANK.length) {
  return WORD_BANK.slice(0, Math.min(count, WORD_BANK.length));
}

// Same as generateWordList(), but pairs each word with its meaning --
// this is what the bulk-loader UI uses so every inserted key already
// carries real definition data instead of a placeholder `true`.
function generateWordEntries(count = WORD_BANK.length) {
  return generateWordList(count).map((word) => [word, getMeaning(word)]);
}

// ============================================================================
// DEMONSTRATION SUITE
// ============================================================================
function line(char = '-') { console.log(char.repeat(78)); }

function main() {
  const tree = new BPlusTree(6400); // order 6400 => up to 63 keys/node, min 31

  line('=');
  console.log('B+ TREE DEMONSTRATION SUITE');
  line('=');

  // --- 1. Manual insertion of a handful of known words -----------------------
  console.log('\n[1] Inserting a small set of hand-picked words (with meanings)...');
  const manual = ['apple', 'banana', 'cherry', 'date', 'elderberry'];
  for (const w of manual) {
    const meaning = tree.insertWord(w); // looks up WORD_MEANINGS automatically
    console.log(`  inserted "${w}" -> ${meaning}`);
  }

  console.log('\n[2] Searching for words just inserted:');
  for (const w of manual) {
    console.log(`  search("${w}") -> ${tree.search(w)}`);
  }
  console.log(`  search("nonexistentword") -> ${tree.search('nonexistentword')}`);

  // --- 3. Bulk insert the full word bank (word + meaning pairs) ----------------
  console.log(`\n[3] Bulk-inserting the full word bank (${WORD_BANK.length} real words, each with a meaning)...`);
  const dataset = generateWordEntries();
  console.time('  bulk insert time');
  for (const [word, meaning] of dataset) tree.insert(word, meaning);
  console.timeEnd('  bulk insert time');
  console.log(`  Total keys in tree: ${tree.size}`);
  console.log(`  Tree height: ${tree.height()}`);
  console.log(`  Leaf count: ${tree.leafCount()}`);
   //-----------------------------------------------------------------------------
  // --- 4. Location-aware search demonstrations ---------------------------------
  //-----------------------------------------------------------------------------

  console.log('\n[4] Searching with full location detail (meaning included):');
  const sampleTargets = [dataset[0][0], dataset[Math.floor(dataset.length / 2)][0], dataset[dataset.length - 1][0], 'zzz_missing_zzz'];
  for (const w of sampleTargets) {
    const info = tree.describeSearch(w);
    if (info.found) {
      console.log(`  "${w}" -> FOUND in leaf #${info.leafOrdinal}/${info.leafCount}, position ${info.leafIndex + 1}/${info.leaf.keys.length}, depth ${info.leafDepth}`);
      console.log(`      meaning: ${info.value}`);
    } else {
      console.log(`  "${w}" -> NOT FOUND (would belong in leaf #${info.leafOrdinal}/${info.leafCount})`);
    }
  }
   
   
  // --- 5. Range scan demo using the leaf linked-list --------------------------
  console.log('\n[5] Range scan demo (first 5 keys from "apple" upward, with meanings):');
  const range = tree.rangeScan('apple', 'apple\uffff').slice(0, 5);
  range.forEach(([k, meaning]) => console.log(`  ${k} -- ${meaning}`));

  //-----------------------------------------------------------------------------
  // --- 6. Deletion demonstrations ----------------------------------------------
  //-----------------------------------------------------------------------------

  console.log('\n[6] Deleting words and verifying tree integrity...');
  console.log(`  size before deletions: ${tree.size}, height: ${tree.height()}`);

  console.log('  deleting "banana" ->', tree.delete('banana'));
  console.log('  search("banana") after delete ->', tree.search('banana'));

  console.log('  deleting "nonexistentword" (should be false) ->', tree.delete('nonexistentword'));

  console.log('  bulk-deleting 2,000 words to force merges/borrows...');
  let deletedCount = 0;
  for (let i = 0; i < 2000 && i < dataset.length; i++) {
    if (tree.delete(dataset[i][0])) deletedCount++;
  }
  console.log(`  successfully deleted: ${deletedCount}`);
  console.log(`  size after deletions: ${tree.size}, height: ${tree.height()}`);

  line('=');
  console.log('DEMONSTRATION COMPLETE');
  line('=');
}

  function searchAndLog(word) {
  word = word.trim().toLowerCase();

  const t0 = performance.now();
  const info = tree.describeSearch(word);   // full root-to-leaf trail
  const elapsedMs = performance.now() - t0;

  const timeLabel = elapsedMs < 1
    ? `${(elapsedMs * 1000).toFixed(1)} microseconds`
    : `${elapsedMs.toFixed(3)} ms`;

  if (info.found) {
    console.log(
      `"${word}" FOUND -- leaf #${info.leafOrdinal}/${info.leafCount}, ` +
      `position ${info.leafIndex + 1}/${info.leaf.keys.length}, depth ${info.leafDepth}`
    );
    console.log(`  meaning: ${info.value}`);
  } else {
    console.log(`"${word}" NOT FOUND (would belong in leaf #${info.leafOrdinal}/${info.leafCount})`);
  }
  console.log(`  search time: ${timeLabel}`);

  return info;
}

// build a tree loaded with all 20,432 words, then search one:
const tree = new BPlusTree(6400);
for (const [word, meaning] of generateWordEntries()) tree.insert(word, meaning);

searchAndLog('bezzants');

// Only auto-run the console demo when this file is executed directly with
// Node (e.g. `node bplus_tree.js`). `typeof` is safe on undeclared globals,
// so this check never throws when the file is instead loaded in a browser
// via <script src="bplus_tree.js"></script>.
if (typeof require !== 'undefined' && typeof module !== 'undefined' && require.main === module) {
  main();
}

// Node/CommonJS export (skipped entirely in a browser, where `module`
// doesn't exist).
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    BPlusTree, BPlusTreeNode, WORD_BANK, WORD_MEANINGS,
    getMeaning, generateWordList, generateWordEntries,
  };
}

// Browser export: top-level `class`/`function` declarations in a classic
// <script> are already visible by name to later <script> tags on the same
// page, but attaching them to `window` too makes the dependency explicit for
// any UI code that wants to reach them as `window.BPlusTree`, etc.
if (typeof window !== 'undefined') {
  window.BPlusTree = BPlusTree;
  window.BPlusTreeNode = BPlusTreeNode;
  window.WORD_BANK = WORD_BANK;
  window.WORD_MEANINGS = WORD_MEANINGS;
  window.getMeaning = getMeaning;
  window.generateWordList = generateWordList;
  window.generateWordEntries = generateWordEntries;
}